// ignore_for_file: lines_longer_than_80_chars

// Unit tests for vault thumbnail generation.
//
// Platform-agnostic (VM + Chrome):
// 1. generateThumbnail for valid images → returns JPEG bytes
// 2. generateThumbnail for PDF/unsupported → null
// 3. generateThumbnail for corrupted bytes → null (no crash)
// 4. generateThumbnail for video > 200 MiB (bytes, no path) → null
// 5. generateThumbnail for invalid video bytes → null (no crash)
// 6. scaling — aspect ratio, degenerate, no-upscale, via decoding the output
// 7. pixel probes — sub-256 images keep real pixels (not white)
// 8. VideoSource create/dispose balance on every video attempt
// 9. path-based video: inaccessible path → null (no crash, no VideoSource)
//
// Chrome-only (skipped on VM):
// 10. real MP4 → JPEG thumbnail of the ~1s frame, not the first frame
// 11. path-based video: blob URL path → thumbnail, no VideoSource created
// 12. path-based video: bytes over the cap + path → thumbnail (no size reject)
//
// Run: flutter test --platform=chrome test/vault_thumbnail_test.dart
//      flutter test test/vault_thumbnail_test.dart

import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/foundation.dart' show kIsWeb;
import 'package:flutter_test/flutter_test.dart';
import 'package:get_thumbnail_video/index.dart' show ImageFormat;
import 'package:get_thumbnail_video/video_thumbnail.dart';
import 'package:image/image.dart' as img;

import 'package:bmo_app/core/platform/video_source.dart';
import 'package:bmo_app/features/vault/data/vault_thumbnail.dart';

import 'video_thumbnail_register.dart';

// ---------------------------------------------------------------------------
// Test data helpers (package:image — no browser APIs)
// ---------------------------------------------------------------------------

Uint8List _createJpeg(int width, int height, {img.Color? color}) {
  final image = img.Image(width: width, height: height, numChannels: 3);
  img.fill(image, color: color ?? img.ColorRgb8(68, 136, 204));
  return Uint8List.fromList(img.encodeJpg(image, quality: 90));
}

Uint8List _createPng(int width, int height, {img.Color? color}) {
  final image = img.Image(width: width, height: height, numChannels: 3);
  img.fill(image, color: color ?? img.ColorRgb8(68, 204, 136));
  return Uint8List.fromList(img.encodePng(image));
}

/// Two-frame animated GIF: red first frame, blue second.
Uint8List _createAnimatedGif(int width, int height) {
  final red = img.Image(width: width, height: height, numChannels: 3);
  img.fill(red, color: img.ColorRgb8(255, 40, 40));
  final blue = img.Image(width: width, height: height, numChannels: 3);
  img.fill(blue, color: img.ColorRgb8(40, 40, 255));

  final encoder = img.GifEncoder(repeat: 0);
  encoder.addFrame(red, duration: 10);
  encoder.addFrame(blue, duration: 10);
  return Uint8List.fromList(encoder.finish()!);
}

img.Image _decode(Uint8List bytes) => img.decodeImage(bytes)!;

img.Pixel _centerPixel(img.Image image) => image.getPixel(
      image.width ~/ 2,
      image.height ~/ 2,
    );

/// 2s 160x90 H.264 (12 fps) generated by AVAssetWriter. Background hue
/// sweeps per frame and a white block moves 5px/frame; the frame at t=1s is
/// visibly different from the first frame.
const String _kProbeMp4Base64 = '';

Uint8List get _probeMp4 => base64Decode(_kProbeMp4Base64);

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

void main() {
  // The video plugin goes through a MethodChannel — needs the binding.
  TestWidgetsFlutterBinding.ensureInitialized();

  // =========================================================================
  // generateThumbnail — image
  // =========================================================================
  group('generateThumbnail (image)', () {
    test('returns JPEG bytes for valid JPEG image', () async {
      final thumb = await generateThumbnail(_createJpeg(8, 6), 'image/jpeg');

      expect(thumb, isNotNull);
      expect(thumb!.length, greaterThan(0));
      // JPEG magic bytes
      expect(thumb[0], 0xFF);
      expect(thumb[1], 0xD8);
    });

    test('returns JPEG bytes for valid PNG image', () async {
      final thumb = await generateThumbnail(_createPng(8, 6), 'image/png');

      expect(thumb, isNotNull);
      expect(thumb!.length, greaterThan(0));
      // Should be re-encoded as JPEG
      expect(thumb[0], 0xFF);
      expect(thumb[1], 0xD8);
    });

    test('returns JPEG bytes for animated GIF (first frame)', () async {
      final thumb =
          await generateThumbnail(_createAnimatedGif(12, 12), 'image/gif');

      expect(thumb, isNotNull);
      expect(thumb![0], 0xFF);
      expect(thumb[1], 0xD8);

      // First frame is red — probe, not just magic bytes.
      final decoded = _decode(thumb);
      final pixel = _centerPixel(decoded);
      expect(pixel.r, greaterThan(150));
      expect(pixel.b, lessThan(120));
    });

    test('returns null for PDF MIME type', () async {
      final pdfBytes = Uint8List.fromList([0x25, 0x50, 0x44, 0x46]); // %PDF
      final thumb = await generateThumbnail(pdfBytes, 'application/pdf');
      expect(thumb, isNull);
    });

    test('returns null for text/plain', () async {
      final textBytes = Uint8List.fromList('hello world'.codeUnits);
      final thumb = await generateThumbnail(textBytes, 'text/plain');
      expect(thumb, isNull);
    });

    test('returns null for application/octet-stream', () async {
      final bytes = Uint8List(100);
      final thumb =
          await generateThumbnail(bytes, 'application/octet-stream');
      expect(thumb, isNull);
    });

    test('returns null for corrupted image bytes', () async {
      final badBytes = Uint8List.fromList([0x00, 0x01, 0x02, 0xFF]);
      final thumb = await generateThumbnail(badBytes, 'image/jpeg');
      expect(thumb, isNull);
    });

    test('returns null for HEIC (no decoder in package:image)', () async {
      // ftyp box with heic brand — real HEIC signature; package:image has
      // no HEIC decoder, so even the full file returns null.
      final heicBytes = Uint8List.fromList([
        0x00, 0x00, 0x00, 0x18, 0x66, 0x74, 0x79, 0x70, // ....ftyp
        0x68, 0x65, 0x69, 0x63, 0x00, 0x00, 0x00, 0x00, // heic....
        0x68, 0x65, 0x69, 0x63, 0x6D, 0x69, 0x66, 0x31, // heicmif1
      ]);
      final thumb = await generateThumbnail(heicBytes, 'image/heic');
      expect(thumb, isNull);
    });

    test('thumbnail size is reasonable (<< 100 KB)', () async {
      final thumb = await generateThumbnail(_createJpeg(8, 6), 'image/jpeg');

      expect(thumb, isNotNull);
      // A 256px JPEG at quality 0.7 should be well under 100 KB.
      expect(thumb!.length, lessThan(100 * 1024));
    });
  });

  // =========================================================================
  // Scaling — verified by decoding the output (no browser APIs)
  // =========================================================================
  group('scaling', () {
    test('landscape image is scaled to fit max dimension', () async {
      final thumb = await generateThumbnail(_createPng(800, 400), 'image/png');
      final decoded = _decode(thumb!);

      // Aspect ratio: 800:400 = 2:1, max dim 256 → 256×128
      expect(decoded.width, 256);
      expect(decoded.height, 128);
    });

    test('portrait image is scaled to fit max dimension', () async {
      final thumb = await generateThumbnail(_createPng(200, 600), 'image/png');
      final decoded = _decode(thumb!);

      // Aspect ratio: 200:600 = 1:3, max dim 256 → 85×256
      expect(decoded.height, 256);
      expect(decoded.width, lessThan(256));
      expect(decoded.width, 85);
    });

    test('small image is NOT upscaled', () async {
      final thumb = await generateThumbnail(_createPng(50, 50), 'image/png');
      final decoded = _decode(thumb!);

      // Should stay 50×50 (not be upscaled).
      expect(decoded.width, 50);
      expect(decoded.height, 50);
    });

    test('square large image is scaled correctly', () async {
      final thumb = await generateThumbnail(_createPng(512, 512), 'image/png');
      final decoded = _decode(thumb!);

      // 512×512 → 256×256
      expect(decoded.width, 256);
      expect(decoded.height, 256);
    });
  });

  // =========================================================================
  // Pixel probes — the case the dart:ui pipeline returned white
  // =========================================================================
  group('pixel probes (sub-256 images)', () {
    test('small JPEG keeps real pixels (not white)', () async {
      final source = img.ColorRgb8(220, 40, 40);
      final thumb =
          await generateThumbnail(_createJpeg(8, 6, color: source), 'image/jpeg');
      final pixel = _centerPixel(_decode(thumb!));

      expect(pixel.r, greaterThan(150));
      expect(pixel.g, lessThan(110));
      expect(pixel.b, lessThan(110));
    });

    test('small PNG keeps real pixels (not white)', () async {
      final source = img.ColorRgb8(40, 40, 220);
      final thumb =
          await generateThumbnail(_createPng(50, 50, color: source), 'image/png');
      final pixel = _centerPixel(_decode(thumb!));

      expect(pixel.b, greaterThan(150));
      expect(pixel.r, lessThan(110));
      expect(pixel.g, lessThan(110));
    });
  });

  // =========================================================================
  // generateThumbnail — video
  // =========================================================================
  group('generateThumbnail (video)', () {
    setUp(() {
      videoSourceCreatedCount = 0;
      videoSourceDisposedCount = 0;
    });

    test('returns null for video bytes over 200 MiB limit', () async {
      final largeBytes = Uint8List(kVideoThumbnailMaxBytes + 1);
      final thumb = await generateThumbnail(largeBytes, 'video/mp4');
      expect(thumb, isNull);

      // Cap is checked before a source is created — nothing to dispose.
      expect(videoSourceCreatedCount, 0);
      expect(videoSourceDisposedCount, 0);
    });

    test('returns null for small but invalid video bytes', () async {
      // 100 bytes of garbage is not a valid video → should return null, not
      // crash.
      final badBytes = Uint8List.fromList(
        List.generate(100, (i) => i % 256),
      );
      final thumb = await generateThumbnail(badBytes, 'video/mp4');
      expect(thumb, isNull);

      // The source was created and disposed even on failure.
      expect(videoSourceCreatedCount, 1);
      expect(videoSourceDisposedCount, 1);
    });

    test('returns null for empty video bytes', () async {
      final empty = Uint8List(0);
      final thumb = await generateThumbnail(empty, 'video/mp4');
      expect(thumb, isNull);

      expect(videoSourceCreatedCount, 1);
      expect(videoSourceDisposedCount, 1);
    });

    // Browser-only: real video decode + frame capture needs a video element.
    test(
      'real MP4 → JPEG thumbnail of the ~1s frame, source disposed',
      skip: !kIsWeb,
      () async {
        // Web tests don't run the plugin registrant — register by hand.
        registerVideoThumbnailForTest();
        videoSourceCreatedCount = 0;
        videoSourceDisposedCount = 0;
        final mp4 = _probeMp4;

        // Reference: first frame (timeMs 1 — avoids the no-seek case of
        // exactly 0, which never fires onSeeked).
        final firstFrameSource = await createVideoSource(mp4, 'video/mp4');
        final firstFrame = await VideoThumbnail.thumbnailData(
          video: firstFrameSource.uri.toString(),
          imageFormat: ImageFormat.JPEG,
          maxWidth: 0,
          maxHeight: 0,
          timeMs: 1,
          quality: 90,
        ).timeout(const Duration(seconds: 10));
        firstFrameSource.dispose();

        final thumb = await generateThumbnail(mp4, 'video/mp4');
        expect(thumb, isNotNull);
        expect(thumb![0], 0xFF);
        expect(thumb[1], 0xD8);

        // Both sources created during this test were disposed.
        expect(videoSourceCreatedCount, 2);
        expect(videoSourceDisposedCount, 2);

        final decoded = _decode(thumb);
        // 160×90 source, no upscale: stays 160×90.
        expect(decoded.width, 160);
        expect(decoded.height, 90);

        // Not black.
        final center = _centerPixel(decoded);
        expect(center.r + center.g + center.b, greaterThan(60));

        // ~1s frame, not the first frame: the moving white block covers the
        // center at t=1s (frame 12, x=60..90) but not at t≈0.
        final firstCenter = _centerPixel(_decode(firstFrame));
        final rDiff = (center.r - firstCenter.r).abs();
        expect(rDiff, greaterThan(80));
      },
    );
  });

  // =========================================================================
  // Video thumbnail — path-based (original file, no cap)
  // =========================================================================
  group('video thumbnail from path', () {
    setUp(() {
      videoSourceCreatedCount = 0;
      videoSourceDisposedCount = 0;
      // No-op on VM; chrome tests hang on plugin channels without it.
      registerVideoThumbnailForTest();
    });

    test('inaccessible path → null, no crash, no VideoSource', () async {
      final thumb = await getThumbnailVideoFromPath('/nonexistent/nope.mp4');
      expect(thumb, isNull);

      // The path route never builds a VideoSource — nothing to dispose.
      expect(videoSourceCreatedCount, 0);
      expect(videoSourceDisposedCount, 0);
    });

    // Browser-only: real video decode + frame capture needs a video element.
    test(
      'blob URL path → thumbnail of the ~1s frame, no VideoSource',
      skip: !kIsWeb,
      () async {
        // Real blob URL over the probe MP4 — the same shape image_picker
        // delivers on web. Created before resetting the counters, so the
        // assertions below attribute only the thumbnail call.
        final source = await createVideoSource(_probeMp4, 'video/mp4');
        videoSourceCreatedCount = 0;
        videoSourceDisposedCount = 0;

        final thumb = await getThumbnailVideoFromPath(source.uri.toString());
        expect(thumb, isNotNull);
        expect(thumb![0], 0xFF);
        expect(thumb[1], 0xD8);

        // The path route never builds a VideoSource.
        expect(videoSourceCreatedCount, 0);
        expect(videoSourceDisposedCount, 0);

        source.dispose();
        expect(videoSourceDisposedCount, 1);

        final decoded = _decode(thumb);
        // 160×90 source, no upscale: stays 160×90.
        expect(decoded.width, 160);
        expect(decoded.height, 90);

        // Not black.
        final center = _centerPixel(decoded);
        expect(center.r + center.g + center.b, greaterThan(60));
      },
    );

    test(
      'bytes over the cap + path → thumbnail (size never checked)',
      skip: !kIsWeb,
      () async {
        final source = await createVideoSource(_probeMp4, 'video/mp4');

        // 200 MiB + 1 — the exact size that kills the bytes route. The path
        // route must never look at these bytes.
        final largeBytes = Uint8List(kVideoThumbnailMaxBytes + 1);

        final thumb = await generateThumbnail(
          largeBytes,
          'video/mp4',
          sourcePath: source.uri.toString(),
        );
        expect(thumb, isNotNull);

        source.dispose();
      },
    );
  });
}
